### uie_batch.py
Top imports: json, subprocess, importlib.util, dataclasses, pathlib.Path, typing.
_load_runner(): loads verification/phase17-graph-recall-multiroute-fusion/run_graph_recall_acceptance.py via spec_from_file_location and returns the module (name it 'run_graph_recall_acceptance').
class SubprocessUieBatchExtractor:
  __init__(self, venv_python: str, worker_script: str, *, timeout_s: float = 600.0) - store all three.
  extract(self, texts: Sequence[str]) -> runner.ExtractionBundle:
    argv = [str(self.venv_python), str(self.worker_script)]
    proc = subprocess.run(argv, input=json.dumps({'texts': [str(t) for t in texts]}).encode('utf-8'), capture_output=True, check=False, timeout=self.timeout_s)
    if proc.returncode != 0: raise RuntimeError('uie extraction worker failed')
    body = json.loads(proc.stdout.decode('utf-8')); documents = []
    for entry in body['documents']: build runner.DocumentExtraction(document_id=str(entry['document_id']), source_text=str(entry['source_text']), normalized_text=str(entry['normalized_text']), entities=tuple(runner.ExtractionEntity(text=str(e['text']), label=str(e['label']), char_start=int(e['char_start']), char_end=int(e['char_end']), confidence=e.get('confidence')) for e in entry['entities']), relations=tuple(runner.ExtractionRelation(subject_text=str(r['subject_text']), subject_type=str(r['subject_type']), relation=str(r['relation']), object_text=str(r['object_text']), object_type=str(r['object_type']), source_text=str(r['source_text'])) for r in entry['relations']))
    return runner.ExtractionBundle(documents=tuple(documents))
class UieBatchExtractor(Protocol): extract(self, texts: Sequence[str]) -> runner.ExtractionBundle

### run_phase17_demo.py
Loads the wave-1 runner with the same _load_runner() helper (RUNNER module object).
Constants: AUTH_ENV = 'OKF_PHASE17_DEMO_AUTHORIZED'; REPORT_NAME = 'phase17_demo_report.md'; VERIFICATION_DIR = Path(__file__).resolve().parent; SKIPPED_REPORT_BODY = '# Phase 17 dual-route demo report\n\nstatus: skipped_not_entered\nreason: authorization gate not satisfied (redacted)\n'
@dataclass(frozen=True) DemoBatch(batch_id: str, texts: tuple[str, ...])
DEMO_BATCHES = (DemoBatch('similar', RUNNER.SAMPLE_TEXTS), DemoBatch('mixed', ('李雷昨天去了上海', '医院的张医生给了诊断', '昨天的球赛很精彩', '股票市场今天上涨')))
@dataclass(frozen=True) DemoDeps(trial_engine: object, uie_extractor: object, llm_extractor: object, reviewer: object, ingestor: object, recall: object, bm25_titles: object)
@dataclass(frozen=True) BatchOutcome(batch_id: str, route: str, status: str, mentions_count: int, identities_count: int, basket_pending: int, relations_total: int, relations_supported: int, relations_rejected: int, ingest_entities: int, recall_hit_count: int, fusion_max_score: float, error_type: str | None = None)
def run_demo(deps: DemoDeps) -> tuple[BatchOutcome, ...]:
  for each batch in DEMO_BATCHES (in order):
    route = 'UNKNOWN'
    try:
      report = deps.trial_engine.run_trial(batch.batch_id, batch.texts)
      decision = trial.decide_route(report)
      route = decision.route.name
      if decision.route is trial.ExtractionRoute.PURE_UIE: bundle = deps.uie_extractor.extract(batch.texts)
      else: bundle = deps.llm_extractor(batch.texts)
      steps = RUNNER.run_pipeline(bundle, batch_id=batch.batch_id, route=route, coverage_ratio=decision.coverage_ratio, reviewer=deps.reviewer, ingestor=deps.ingestor, recall=deps.recall, bm25_titles=deps.bm25_titles)
      outcome = BatchOutcome(batch_id=batch.batch_id, route=route, status='executed', mentions_count=int(steps['mentions_count']), identities_count=int(steps['identities_count']), basket_pending=int(steps['basket_pending']), relations_total=int(steps['relations_total']), relations_supported=int(steps['relations_supported']), relations_rejected=int(steps['relations_pending']), ingest_entities=int(steps['ingest_entities']), recall_hit_count=int(steps['recall_hit_count']), fusion_max_score=float(steps['fusion_max_score']))
    except Exception as exc:
      outcome = BatchOutcome(batch_id=batch.batch_id, route=route, status='failed', mentions_count=0, identities_count=0, basket_pending=0, relations_total=0, relations_supported=0, relations_rejected=0, ingest_entities=0, recall_hit_count=0, fusion_max_score=0.0, error_type=type(exc).__name__)
    yield-append outcome; return tuple(outcomes)
def build_demo_report(outcomes: Sequence[BatchOutcome]) -> str:
  lines = ['# Phase 17 dual-route demo report', '']
  for o in outcomes:
    lines += ['## batch: ' + o.batch_id, '- route: ' + o.route, '- status: ' + o.status, '- mentions_count: ' + str(o.mentions_count), '- identities_count: ' + str(o.identities_count), '- relations_supported: ' + str(o.relations_supported), '- relations_rejected: ' + str(o.relations_rejected), '- relations_total: ' + str(o.relations_total), '- ingest_entities: ' + str(o.ingest_entities), '- recall_hit_count: ' + str(o.recall_hit_count), '- fusion_max_score: ' + format(o.fusion_max_score, '.6f')]
    if o.error_type is not None: lines.append('- error_type: ' + o.error_type)
    lines.append('')
  return '\n'.join(lines)
def main(argv: Sequence[str], *, target_uri: str, deps_factory: object | None = None) -> int:
  if argv: raise ValueError('demo runner takes no command line arguments; target_uri is programmatic only')
  if os.environ.get(AUTH_ENV) != '1': write SKIPPED_REPORT_BODY to VERIFICATION_DIR / REPORT_NAME (utf-8); return 1 WITHOUT calling deps_factory.
  deps = (deps_factory or build_deps)(target_uri); outcomes = run_demo(deps); report = build_demo_report(outcomes)
  (VERIFICATION_DIR / REPORT_NAME).write_text(report, encoding='utf-8'); print(report)
  return 0 if all(o.status == 'executed' for o in outcomes) else 1
def build_deps(target_uri: str) -> DemoDeps (live-only, lazy imports, no tests): llm trial engine via llm_openai trial_engine.LlmTrialEngine(OpenAICompatClient(...), frozenset(8 predicates)); llm_extractor = callable that calls client.complete per text with a JSON extraction prompt, parses {'entities': [...], 'relations': [...]} and builds runner.DocumentExtraction rows (deterministic char offsets via text.index on the normalized text, confidence None, document_id f'demo-{batch}-n'); uie_extractor = SubprocessUieBatchExtractor with paths from env (PHASE17_UIE_PYTHON, PHASE17_UIE_WORKER); reviewer = LlmRelationReviewer(client); ingestor = LightragKgIngestor; recall/bm25 same wiring as wave-1 build_deps. Tests never call build_deps.
### Static requirements
from __future__ import annotations; full annotations; black/ruff/mypy/py_compile clean; deterministic report; no I/O except the report file; subprocess only inside SubprocessUieBatchExtractor.

